fn is_palindrome(text: Vec<char>) -> bool {
    fn lower_ascii(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            // Safe because 'A'..='Z' are ASCII and map directly to 'a'..='z'
            ((c as u8) + (b'a' - b'A')) as char
        } else {
            c
        }
    }

    let n = text.len();
    for i in 0..(n / 2) {
        let a = lower_ascii(text[i]);
        let b = lower_ascii(text[n - 1 - i]);
        if a != b {
            return false;
        }
    }
    true
}